from __future__ import annotations

import json
import os
from collections.abc import Iterable, Iterator, Mapping
from typing import Any

import event_store
from event_store import append_event
from signature_utils import verify_signature

#: Header carrying the HMAC-SHA256 of the raw request body.
SIGNATURE_HEADER = "X-Webhook-Signature"

#: Fields every accepted payment event must carry as non-empty strings.
REQUIRED_EVENT_FIELDS = ("event_id", "event_type", "account_id")

#: Environment variable holding the shared receiver secret.
SECRET_ENV_VAR = "WEBHOOK_SECRET"


def _rejected(reason: str) -> dict[str, Any]:
    """Build a rejection response; nothing is queued for these."""

    return {"status": "rejected", "reason": reason}


def _accepted(event_id: str) -> dict[str, Any]:
    """Build the documented acceptance response."""

    return {"status": "accepted", "event_id": event_id}


def _header_pairs(headers: Any) -> Iterator[tuple[Any, Any]]:
    """Yield (name, value) pairs from a mapping-like or pair-sequence header set."""

    if isinstance(headers, Mapping):
        yield from headers.items()
        return
    items = getattr(headers, "items", None)
    if callable(items):
        try:
            yield from items()
        except TypeError:
            return
        return
    if isinstance(headers, Iterable) and not isinstance(headers, (str, bytes, bytearray)):
        yield from headers


def _find_signature(headers: Any) -> Any:
    """Return the signature header value, matching the name case-insensitively."""

    fallback: Any = None
    for pair in _header_pairs(headers):
        try:
            name, value = pair
        except (TypeError, ValueError):
            continue
        if not isinstance(name, str):
            continue
        if name == SIGNATURE_HEADER:
            return value
        if fallback is None and name.lower() == SIGNATURE_HEADER.lower():
            fallback = value
    return fallback


def _as_bytes(body: Any) -> bytes | None:
    """Normalise the request body to bytes, or ``None`` when unusable."""

    if isinstance(body, bytes):
        return body
    if isinstance(body, (bytearray, memoryview)):
        return bytes(body)
    if isinstance(body, str):
        return body.encode("utf-8")
    return None


def _parse_event(body: bytes) -> dict[str, Any] | None:
    """Decode and validate one payment event, or ``None`` when malformed."""

    try:
        payload = json.loads(body.decode("utf-8"))
    except (UnicodeDecodeError, ValueError):
        return None
    if not isinstance(payload, dict):
        return None
    for field in REQUIRED_EVENT_FIELDS:
        value = payload.get(field)
        if not isinstance(value, str) or not value:
            return None
    return payload


def _append_event(event: dict[str, Any]) -> None:
    """Persist through the existing ``event_store.append_event()`` helper.

    Resolved at call time so the documented event-store seam stays swappable.
    """

    getattr(event_store, "append_event", append_event)(event)


def handle_webhook(request: Mapping[str, Any]) -> dict[str, Any]:
    """Validate and enqueue one payment event.

    Deliveries are authenticated with HMAC-SHA256 over the *raw* body using the
    secret in ``WEBHOOK_SECRET``. ``deployment.json`` exposes this handler on the
    public ``/callbacks/linkweave`` route with no authenticating middleware in
    front of it, so the signature is **mandatory**: a delivery whose
    ``X-Webhook-Signature`` header is missing, malformed, or wrong is rejected and
    never reaches the event store.

    The legacy relay adapter only checked the signature when the header happened
    to be present (``if signature and not verify_signature(...)``). That
    header-optional "compatibility path" is deliberately *not* carried over: on a
    public route it is an authentication bypass -- an attacker simply omits the
    header to enqueue forged payment events. Everything else in the receiver
    guide (response shapes, event parsing, single append through the event store,
    pass-through of event fields) is preserved.
    """

    if not isinstance(request, Mapping):
        return _rejected("invalid request")

    secret = os.environ.get(SECRET_ENV_VAR)
    if not secret:
        # Fail closed: without a configured secret no delivery can be trusted.
        return _rejected("receiver not configured")

    body = _as_bytes(request.get("body"))
    if body is None:
        return _rejected("invalid payload")

    # Authenticate before parsing so unauthenticated bytes are never inspected
    # beyond the signature comparison, and never queued.
    signature = _find_signature(request.get("headers"))
    if not verify_signature(body, signature, secret):
        return _rejected("invalid signature")

    event = _parse_event(body)
    if event is None:
        return _rejected("invalid payload")

    # Event fields are passed through unchanged for downstream schema
    # compatibility, and appended exactly once.
    _append_event(event)
    return _accepted(event["event_id"])
