{"content":""""Authentication and validation tests for the Linkweave webhook receiver.

The route in ``deployment.json`` is public ingress with no authenticating
middleware, so a missing or forged ``X-Webhook-Signature`` header must be
rejected without touching the event store.
"""

from __future__ import annotations

import json
import os
import tempfile
import unittest

from signature_utils import signature_for
from webhooks import handle_webhook

SECRET = "unit-test-webhook-secret"


class ReceiverSecurityTests(unittest.TestCase):
    def setUp(self):
        self.secret = SECRET
        self.log = tempfile.NamedTemporaryFile(delete=False)
        self.log.close()
        os.environ["WEBHOOK_SECRET"] = self.secret
        os.environ["WEBHOOK_EVENTS"] = self.log.name

    def tearDown(self):
        os.unlink(self.log.name)
        os.environ.pop("WEBHOOK_SECRET", None)
        os.environ.pop("WEBHOOK_EVENTS", None)

    def stored_events(self) -> list[dict]:
        with open(self.log.name, encoding="utf-8") as handle:
            return [json.loads(line) for line in handle if line.strip()]

    @staticmethod
    def signed_request(event: dict, secret: str = SECRET) -> dict:
        body = json.dumps(event, sort_keys=True).encode("utf-8")
        return {
            "headers": {"X-Webhook-Signature": signature_for(body, secret)},
            "body": body,
        }

    def test_missing_signature_header_is_rejected_and_not_queued(self):
        """No header-optional bypass: unsigned deliveries must never be accepted."""
        body = json.dumps(
            {"event_id": "evt-forged", "event_type": "invoice.paid", "account_id": "acct-9"}
        ).encode("utf-8")
        response = handle_webhook({"headers": {}, "body": body})
        self.assertEqual(response, {"status": "rejected", "reason": "invalid signature"})
        self.assertEqual(self.stored_events(), [])

    def test_missing_headers_entirely_is_rejected(self):
        body = json.dumps(
            {"event_id": "evt-forged", "event_type": "invoice.paid", "account_id": "acct-9"}
        ).encode("utf-8")
        self.assertEqual(handle_webhook({"body": body})["status"], "rejected")
        self.assertEqual(self.stored_events(), [])

    def test_signature_from_wrong_secret_is_rejected(self):
        event = {"event_id": "evt-002", "event_type": "invoice.paid", "account_id": "acct-1"}
        response = handle_webhook(self.signed_request(event, secret="attacker-secret"))
        self.assertEqual(response, {"status": "rejected", "reason": "invalid signature"})
        self.assertEqual(self.stored_events(), [])

    def test_tampered_body_is_rejected(self):
        request = self.signed_request(
            {"event_id": "evt-003", "event_type": "invoice.paid", "account_id": "acct-1"}
        )
        tampered = json.dumps(
            {"event_id": "evt-003", "event_type": "invoice.refunded", "account_id": "acct-2"}
        ).encode("utf-8")
        request["body"] = tampered
        self.assertEqual(handle_webhook(request)["status"], "rejected")
        self.assertEqual(self.stored_events(), [])

    def test_malformed_signature_header_is_rejected(self):
        body = b'{"event_id": "evt-004", "event_type": "invoice.paid", "account_id": "a"}'
        response = handle_webhook({"headers": {"X-Webhook-Signature": body}, "body": body})
        self.assertEqual(response["status"], "rejected")
        self.assertEqual(self.stored_events(), [])

    def test_missing_secret_configuration_fails_closed(self):
        os.environ.pop("WEBHOOK_SECRET")
        event = {"event_id": "evt-005", "event_type": "invoice.paid", "account_id": "acct-1"}
        self.assertEqual(handle_webhook(self.signed_request(event))["status"], "rejected")
        self.assertEqual(self.stored_events(), [])

    def test_valid_signed_event_is_queued_exactly_once_with_fields_intact(self):
        event = {
            "event_id": "evt-006",
            "event_type": "invoice.paid",
            "account_id": "acct-1",
            "amount_cents": 4200,
            "currency": "EUR",
        }
        response = handle_webhook(self.signed_request(event))
        self.assertEqual(response, {"status": "accepted", "event_id": "evt-006"})
        self.assertEqual(self.stored_events(), [event])

    def test_lowercase_signature_header_name_is_accepted(self):
        event = {"event_id": "evt-007", "event_type": "invoice.paid", "account_id": "acct-1"}
        request = self.signed_request(event)
        request["headers"] = {"x-webhook-signature": request["headers"]["X-Webhook-Signature"]}
        self.assertEqual(handle_webhook(request)["status"], "accepted")
        self.assertEqual(self.stored_events(), [event])

    def test_signed_but_schema_invalid_events_are_rejected(self):
        for payload in (
            b"not-json",
            b"",
            b"[1, 2, 3]",
            b'"a string"',
            b"null",
            b'{"event_id": "evt-x"}',
            b'{"event_id": "evt-x", "event_type": "invoice.paid", "account_id": null}',
            b'{"event_id": "", "event_type": "invoice.paid", "account_id": "acct-1"}',
            b'{"event_id": 7, "event_type": "invoice.paid", "account_id": "acct-1"}',
            "é".encode("latin-1"),
        ):
            with self.subTest(payload=payload):
                response = handle_webhook(
                    {
                        "headers": {"X-Webhook-Signature": signature_for(payload, self.secret)},
                        "body": payload,
                    }
                )
                self.assertEqual(response["status"], "rejected")
        self.assertEqual(self.stored_events(), [])

    def test_non_mapping_request_is_rejected(self):
        self.assertEqual(handle_webhook(None)["status"], "rejected")  # type: ignore[arg-type]
        self.assertEqual(self.stored_events(), [])


if __name__ == "__main__":
    unittest.main()
